WITH sales_agg AS (SELECT cs_call_center_sk, SUM(cs_net_paid) AS total_sales, SUM(cs_net_profit) AS total_profit FROM catalog_sales GROUP BY cs_call_center_sk), returns_agg AS (SELECT cr_call_center_sk, SUM(cr_return_amount) AS total_return, SUM(cr_net_loss) AS total_loss FROM catalog_returns GROUP BY cr_call_center_sk), reason_counts AS (SELECT cr.cr_call_center_sk, r.r_reason_desc, COUNT(*) AS cnt FROM catalog_returns cr JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk GROUP BY cr.cr_call_center_sk, r.r_reason_desc), reason_agg AS (SELECT cr_call_center_sk, r_reason_desc, ROW_NUMBER() OVER (PARTITION BY cr_call_center_sk ORDER BY cnt DESC) AS rn FROM reason_counts) SELECT cc.cc_name, cc.cc_employees, CASE WHEN cc.cc_employees >= 5000 THEN 'Large' WHEN cc.cc_employees >= 1000 THEN 'Medium' ELSE 'Small' END AS size_category, COALESCE(s.total_sales,0) AS total_sales, COALESCE(r.total_return,0) AS total_return, COALESCE(s.total_profit,0) - COALESCE(r.total_loss,0) AS net_profit_adj, RANK() OVER (ORDER BY COALESCE(s.total_profit,0) - COALESCE(r.total_loss,0) DESC) AS profit_rank, ra.r_reason_desc AS top_return_reason FROM call_center cc LEFT JOIN sales_agg s ON cc.cc_call_center_sk = s.cs_call_center_sk LEFT JOIN returns_agg r ON cc.cc_call_center_sk = r.cr_call_center_sk LEFT JOIN reason_agg ra ON cc.cc_call_center_sk = ra.cr_call_center_sk AND ra.rn = 1 ORDER BY profit_rank LIMIT 20
